    env.update({"u0": 0.5, "u1": 0.0, "q0": 0.3, "q1": 0.0})
    try:
        d = float(run(env)["d"])
    except Exception:
        return probs
    ref = 2.0 * math.atanh(abs((0.3 - 0.5) / (1.0 - 0.5 * 0.3)))
